    "Befolgen Sie alle lokalen Vorschriften und Gesetze bezüglich verschreibungspflichtiger Substanzen.",
    "Lagern Sie Medikamente fern von Badezimmern oder Küchen, wo Feuchtigkeitsniveaus häufig schwanken.",
