    "Suchen Sie dringende medizinische Pflege, wenn schwerer Schwindel, Ohnmacht oder plötzliche Schwäche auftritt.",
    "Befolgen Sie immer die Anweisungen Ihres Gesundheitsdienstleisters bezüglich Dosierung und Anwendung."
